"from bs4 import BeautifulSoup\n\nwith open('tests/workday/Systems Software Engineer - New College Grad 2026.htm', 'r', encoding='utf-8', errors='ignore') as f:\n    soup = BeautifulSoup(f.read(), 'html.parser')\n\ninputs = soup.find_all('input', {'type': 'file'})\nfor inp in inputs:\n    print(f\"File input: parent={inp.parent.name}, aid={inp.get('data-automation-id')}, id={inp.get('id')}, name={inp.get('name')}\")\n    # print all attributes\n    print(f\"attrs: {inp.attrs}\")\n"